//
// Returns the same *bun.SelectQuery so it can be chained fluently:
//
//	accountingsynccol.AccountingSyncRecordScopeTenant(sq, ti).
//		Where(accountingsynccol.AccountingSyncRecordColumns.ID.Eq(), id)
func AccountingSyncRecordScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return buncolgen.ScopeTenant(q, AccountingSyncRecordColumns.OrganizationID, AccountingSyncRecordColumns.BusinessUnitID, ti)
}

